var MyCircularDeque = function(k) {
    this.k = k;
    this.q = new Array(k);
    this.head = 0;
    this.count = 0;
};

/** 
 * @param {number} value
 * @return {boolean}
 */
MyCircularDeque.prototype.insertFront = function(value) {
    if (this.isFull()) return false;
    this.head = (this.head - 1 + this.k) % this.k;
    this.q[this.head] = value;
    this.count++;
    return true;
};

/** 
